CREATE TABLE IF NOT EXISTS project_underwriting_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, economic_score numeric(6,2) DEFAULT 0, legal_score numeric(6,2) DEFAULT 0, evidence_score numeric(6,2) DEFAULT 0, valuation_score numeric(6,2) DEFAULT 0, risk_score numeric(6,2) DEFAULT 0, governance_score numeric(6,2) DEFAULT 0, overall_score numeric(6,2) DEFAULT 0, status text NOT NULL DEFAULT 'not_ready', strengths jsonb NOT NULL DEFAULT '[]'::jsonb, weaknesses jsonb NOT NULL DEFAULT '[]'::jsonb, required_actions jsonb NOT NULL DEFAULT '[]'::jsonb, model_version text NOT NULL DEFAULT 'OV-UNDERWRITE-V1', assessed_at timestamptz NOT NULL DEFAULT now());